export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-data-[invalid]:border-destructive group-data-[invalid]:hover:border-destructive group-data-[invalid]:focus-within:border-destructive group-data-[invalid]:focus-within:hover:border-destructive group-data-[invalid]:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-data-[disabled]:bg-muted group-data-[disabled]:opacity-60 group-data-[disabled]:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground data-[pressed]:bg-muted data-[pressed]:text-foreground data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-2 data-[focus-visible]:outline-solid data-[focus-visible]:outline-ring data-[disabled]:cursor-default data-[disabled]:opacity-50";

"use client";

import {
  ColorField as AriaColorField,
  type ColorFieldProps,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  Text,
} from "react-aria-components";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
} from "./field-styles";

export function ColorField({
  className,
  label,
  description,
  children,
  ...props
}: ColorFieldProps &
  React.RefAttributes<HTMLDivElement> & {
    label?: string;
    description?: string;
  }) {
  return (
    <AriaColorField
      {...props}
      data-slot="color-field"
      className={composeRenderProps(className, (className) =>
        cn("grid gap-2", className),
      )}
    >
      {children ?? (
        <>
          {label && (
            <Label data-slot="color-field-label" className={fieldLabelStyles}>
              {label}
            </Label>
          )}
          <Input
            data-slot="color-field-input"
            className={cn(fieldInputStyles, "px-3.5")}
          />
          {description && (
            <Text
              slot="description"
              data-slot="color-field-description"
              className={fieldDescriptionStyles}
            >
              {description}
            </Text>
          )}
          <FieldError
            data-slot="color-field-error"
            className={fieldErrorStyles}
          />
        </>
      )}
    </AriaColorField>
  );
}

"use client";

import {
  ColorSwatch as AriaColorSwatch,
  type ColorSwatchProps,
  composeRenderProps,
} from "react-aria-components";
import { cn } from "./utils";

export function ColorSwatch({ className, style, ...props }: ColorSwatchProps) {
  return (
    <AriaColorSwatch
      {...props}
      data-slot="color-swatch"
      className={composeRenderProps(className, (className) =>
        cn("size-9 shrink-0 rounded-md ring-1 ring-foreground/20", className),
      )}
      style={composeRenderProps(style, (style, { color }) => ({
        background: `linear-gradient(${color}, ${color}), repeating-conic-gradient(var(--border) 0% 25%, var(--background) 0% 50%) 50% / 12px 12px`,
        ...style,
      }))}
    />
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { cn } from "./utils";

function edgeOffset(placement: string | null) {
  switch (placement) {
    case "top":
      return { x: 0, y: 5 };
    case "left":
      return { x: 5, y: 0 };
    case "right":
      return { x: -5, y: 0 };
    default:
      return { x: 0, y: -5 };
  }
}

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { opacity: 0, ...edgeOffset(placement), scale: 0.98 }
            }
            animate={
              isExiting
                ? {
                    opacity: 0,
                    ...(reduceMotion ? {} : edgeOffset(placement)),
                    scale: reduceMotion ? 1 : 0.99,
                  }
                : { opacity: 1, x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: reduceMotion ? 0 : isExiting ? 0.14 : 0.2,
              ease: [0.23, 1, 0.32, 1],
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-5 text-popover-foreground shadow-[var(--shadow-float)] outline-none data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  ColorPicker as AriaColorPicker,
  type ColorPickerProps as AriaColorPickerProps,
  Dialog as AriaDialog,
  ColorArea,
  ColorSlider,
  ColorThumb,
  DialogTrigger,
  Label,
  SliderTrack,
} from "react-aria-components";
import { Button } from "./button";
import { ColorField } from "./color-field";
import { ColorSwatch } from "./color-swatch";
import { Popover } from "./popover";

export interface ColorPickerProps
  extends Omit<AriaColorPickerProps, "children"> {
  label?: string;
  children?: AriaColorPickerProps["children"];
}

export function ColorPicker({
  label = "Choose color",
  children,
  ...props
}: ColorPickerProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaColorPicker {...props} data-slot="color-picker">
      {children ?? (
        <DialogTrigger>
          <Button variant="outline">
            <ColorSwatch className="size-6" />
            {label}
          </Button>
          <Popover placement="bottom start" className="w-64 p-4">
            <AriaDialog
              aria-label={`${label} controls`}
              className="grid gap-4 outline-none"
            >
              <ColorArea
                data-slot="color-picker-area"
                colorSpace="hsb"
                xChannel="saturation"
                yChannel="brightness"
                aria-label="Saturation and brightness"
                className="aspect-square w-full rounded-lg ring-1 ring-inset ring-foreground/20"
              >
                <ColorThumb
                  data-slot="color-picker-area-thumb"
                  className="relative size-5 rounded-full border-2 border-white shadow-[var(--shadow-card)] ring-1 ring-black/50 outline-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-solid data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring"
                >
                  {({ isDragging }) => (
                    <motion.span
                      aria-hidden="true"
                      className="pointer-events-none absolute -inset-1 rounded-full ring-2 ring-primary/60"
                      initial={false}
                      animate={{
                        opacity: isDragging ? 1 : 0,
                        scale: isDragging ? 1 : 0.85,
                      }}
                      transition={{ duration: reduceMotion ? 0 : 0.16 }}
                    />
                  )}
                </ColorThumb>
              </ColorArea>
              <ColorSlider
                data-slot="color-picker-hue"
                colorSpace="hsb"
                channel="hue"
                className="grid gap-2"
              >
                <Label className="text-sm font-medium">Hue</Label>
                <SliderTrack className="relative h-5 rounded-full ring-1 ring-inset ring-foreground/20">
                  <ColorThumb
                    data-slot="color-picker-hue-thumb"
                    className="relative top-1/2 size-6 rounded-full border-2 border-white shadow-[var(--shadow-card)] ring-1 ring-black/50 outline-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring"
                  >
                    {({ isDragging }) => (
                      <motion.span
                        aria-hidden="true"
                        className="pointer-events-none absolute -inset-1 rounded-full ring-2 ring-primary/60"
                        initial={false}
                        animate={{
                          opacity: isDragging ? 1 : 0,
                          scale: isDragging ? 1 : 0.85,
                        }}
                        transition={{ duration: reduceMotion ? 0 : 0.16 }}
                      />
                    )}
                  </ColorThumb>
                </SliderTrack>
              </ColorSlider>
              <ColorField label="Hex" />
            </AriaDialog>
          </Popover>
        </DialogTrigger>
      )}
    </AriaColorPicker>
  );
}
